CREATE TABLE public.produtos (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "PRODUTO" text NOT NULL,
  quantidade_estoque integer NULL,
  estoque_atualizado_em timestamptz NULL
);

GRANT SELECT ON TABLE public.produtos TO anon, authenticated;
GRANT ALL ON TABLE public.produtos TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.produtos_id_seq TO service_role;

ALTER TABLE public.produtos ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Catalog stock is publicly readable"
ON public.produtos
FOR SELECT
TO anon, authenticated
USING (true);

